function readingCanAct(){return readingActive()&&!readingState.done&&!readingState.paused&&!readingState.finished;}
function readingWrong(message='Let’s look again. A grown-up can show one example.'){if(!readingCanAct())return;readingState.message=message;readingRender();}
function readingChoose(value){if(!readingCanAct())return;const s=readingState,g=readingGame(s.id);let answer=s.item;if(g.mode==='count')answer=String(s.word.tiles.length);if(g.mode==='swap')answer=s.word.tiles[s.change];if(g.mode==='meaning')answer=s.word.picture;if(g.mode==='note')answer=readingWord(s.item.replace(/[.!]/g,'').split(' ').at(-1)).picture;if(g.mode==='ending')answer=s.item.includes('naps')?'nap':s.item.includes('sits')?'sit':'tap';const extra=readingMoreAnswer();if(extra!==null)answer=extra;if(value===answer)readingSuccess('choice');else readingWrong();}
function readingPart(id){if(!readingCanAct())return;const s=readingState,paths=readingLetterPaths[s.item];if(id==='x'||!paths[+id])return readingWrong('That piece belongs to another letter. Look at the model.');if(s.parts.includes(+id))return;s.parts.push(+id);if(s.parts.length===paths.length)readingSuccess('choice');else readingRender();}
function readingPlace(bankIndex,slotIndex){if(!readingCanAct())return;const s=readingState;if(!Number.isInteger(bankIndex)||!s.bank[bankIndex]||s.slots.includes(bankIndex))return;const index=slotIndex===undefined?s.slots.indexOf(null):slotIndex;if(index<0||index>=s.slots.length)return;s.slots[index]=bankIndex;readingCheckBuild();}
function readingRemove(index){if(!readingCanAct())return;const s=readingState;if(s.slots[index]===null)return;s.slots[index]=null;s.message='';s.phase='';readingRender();}
function readingMoveSlot(from,to){if(!readingCanAct()||from===to)return;const s=readingState;if(from<0||to<0||from>=s.slots.length||to>=s.slots.length)return;[s.slots[from],s.slots[to]]=[s.slots[to],s.slots[from]];readingCheckBuild();}
function readingCheckBuild(){const s=readingState;if(s.slots.some(v=>v===null)){s.message='';readingRender();return;}const ok=s.slots.every((v,i)=>s.bank[v]===s.word.tiles[i]);if(!ok){s.message='Some tiles need moving. Tap a box to return its tile, or swap two filled boxes.';readingRender();return;}if(readingGame(s.id).mode==='bridge'){s.phase='blend';s.message='The bridge is ready. Blend together while the duck crosses.';readingRender();}else readingSuccess('built');}
function readingDestination(destination){if(!readingCanAct())return;const s=readingState;const answer=s.item==='cat in bag'?'bag':s.item==='hat on cat'?'cat':'mat';if(destination===answer)readingSuccess('meaning');else readingWrong('Compare the caption and the place. Try with your grown-up.');}
function readingBindDrag(){if(typeof TouchPlay==='undefined'||!readingCanAct())return;const q=sel=>app.querySelector(sel),qa=sel=>[...app.querySelectorAll(sel)];qa('[data-reading-choice]').forEach(el=>TouchPlay.bind(el,{targets:()=>[q('[data-reading-home="choice"]')].filter(Boolean),drop:()=>readingChoose(el.dataset.readingChoice)}));qa('[data-reading-part]:not(:disabled)').forEach(el=>TouchPlay.bind(el,{targets:()=>[q('[data-reading-home="parts"]')],drop:()=>readingPart(el.dataset.readingPart)}));qa('[data-reading-tile]:not(:disabled)').forEach(el=>TouchPlay.bind(el,{targets:()=>qa('[data-reading-slot]'),drop:target=>readingPlace(+el.dataset.readingTile,+target.dataset.readingSlot)}));qa('[data-reading-slot]').filter(el=>readingState.slots[+el.dataset.readingSlot]!==null).forEach(el=>TouchPlay.bind(el,{targets:()=>qa('[data-reading-slot]'),drop:target=>readingMoveSlot(+el.dataset.readingSlot,+target.dataset.readingSlot)}));const prop=q('#readingProp');if(prop)TouchPlay.bind(prop,{targets:()=>qa('[data-reading-target]'),drop:target=>readingDestination(target.dataset.readingTarget)});}
function readingSchedule(){readingCancel();const s=readingState;if(!readingActive(s)||s.paused||!s.done||typeof CourseFlow!=='undefined'&&!CourseFlow.enabled)return;readingTimer=setTimeout(()=>{readingTimer=null;if(!readingActive(s)||s.paused||typeof CourseFlow!=='undefined'&&CourseFlow.paused)return;readingNext();},s.lastKind==='shared'?1300:850);}
function readingSuccess(kind){if(!readingCanAct())return;const s=readingState;s.done=true;s.lastKind=kind;s.observations.push({response:kind,adultCueOrHint:s.help,colourCues:readingGame(s.id).wordPlay?wordPlayDisplay.ink!=='plain':readingDisplay.colour&&readingGame(s.id).mode!=='puppet-program',...(readingGame(s.id).wordPlay?{displayMode:wordPlayDisplay.ink,pictureChoiceSetting:s.wp.choices}:{}),round:s.round+1});const mode=readingGame(s.id).mode,w=s.word?.word;const messages={parts:`Great! You built ${s.item}.`,case:`${s.item.toUpperCase()} and ${s.item} belong together!`,font:'Same letter, different outfit!',mnemonic:`A plain ${s.item} for our delivery!`,sound:`You found ${s.item}!`,retrieve:`Welcome back, ${s.item}!`,count:`${s.word?.tiles.length} sound steps for ${w}!`,boxes:`Packed! These spellings make ${w}.`,spell:`The new label says ${w}!`,missing:`The robot’s repaired word says ${w}!`,swap:`One change made ${w}!`,digraph:'Two letters can carry one sound: sh!',scene:`You made “${s.item}” happen!`,meaning:`The sign says ${w}!`,note:`Our friend has a ${s.item.replace(/[.!]/g,'').split(' ').at(-1)}!`,action:`The cat can ${s.item}!`,ending:'That ending fits our little page!',pretend:`Meet ${s.item}, the tiny space potato!`,parcel:`A ${w} in the parcel. What a delivery!`,book:'Another little page explored together!',slide:'Thanks for blending and sliding together!',bridge:'The duck crossed our word bridge!'};s.message=readingMoreMessage()||messages[mode]||(kind==='shared'?'Thanks for reading and exploring together!':'Great! You made something happen!');readingRender();readingSchedule();}
function readingNext(){const s=readingState;if(!readingActive(s)||s.paused||!s.done)return;readingCancel();if(s.round+1>=s.total){readingFinish();return;}s.round++;s.hidden=false;s.propSelected=false;readingPrepare();readingRender();app.querySelector('.reading-invitation')?.focus({preventScroll:true});}
function readingPause(value){const s=readingState;if(!readingActive(s))return;readingCancel();s.paused=value;readingRender();if(!value&&s.done)readingSchedule();}
function readingFinish(){const s=readingState;if(!readingActive(s)||s.finished)return;readingCancel();const c=skillContext;if(c?.courseId===s.courseId){skillNotes[c.courseId]??={};skillNotes[c.courseId].activities??={};skillNotes[c.courseId].activities[c.index]=true;skillNotes[c.courseId].readingPractice??={};skillNotes[c.courseId].readingPractice[c.index]={explored:true,responses:s.observations};skillSave();}s.finished=true;readingRender();}
function readingParentGuide(){return `<p>These adult-supported starter courses support learning letters and beginning to read. They use selected letters, short words, and captions; this is not a complete alphabet or school phonics programme. They use English examples and need an adult to model the sounds, support blending, and discuss meaning. There is no recorded voice or speech recognition.</p><h3>Choose the difficulty, not a diagnosis</h3><p>Matching a letter, recalling its sound, blending a word, spelling it, and understanding a message are different tasks. Start with the relevant course and taught spellings. Children do not have to finish the prereading courses, pronounce every sound clearly, or write neatly before receiving reading instruction.</p><div class="reading-guide-courses">${readingCourses.map(c=>`<button class="secondary" data-reading-course="${c.id}"><b>${c.title}</b><span>${c.need}</span></button>`).join('')}</div><h3>Model, then invite a response</h3><p>Show a small step. Use the grown-up cue when you need the current word or sound, then close it for listening choices. Say a consonant’s sound rather than its letter name when blending, without adding an unnecessary “uh”. Stretch sounds such as m or s comfortably; keep stop sounds brief. Ask the child’s teacher for a model when unsure. The slash cues here are teaching reminders, not a complete pronunciation guide.</p><h3>Match the teaching language and sequence</h3><p>Spellings, example words, accents, fonts, and helper words need to fit the child’s school programme. The app currently supplies English content. Introduce sh before its activities. Read any untaught helper words aloud; do not expect children to guess from pictures. Do not use these courses as a translated phonics programme without adapting and reviewing the language-specific content.</p><h3>What the app can—and cannot—check</h3><p>A correct tile or picture can be checked on screen. A slider finishing, a parcel opening, or a page turning records shared practice, not an independently decoded word. No microphone or oral-reading score is used. Notice retention on another day and a new example away from the screen. Progress records only explored activities and response types; it is not a diagnostic or mastery score.</p><h3>If it is difficult</h3><p>Offer a model, fewer demands, a reminder, or a break. Use pointing, speech, signs, AAC, keyboard access, or adult-entered choices. Do not remove usual communication or movement supports. Tracing is not required. Repeated confusion or distress deserves a discussion with the teacher or relevant specialist, rather than more compulsory rounds.</p>${readingColourGuide()}${readingEvidence({id:'overview'})}`;}
const readingPreviousParents=prParents;
prParents=function(...args){readingPreviousParents(...args);if(!app.querySelector('[data-pr-parent="research"][aria-pressed="true"]'))return;const section=document.createElement('details');section.className='pr-research-section';section.innerHTML='<summary>Letters & starting to read</summary><div>'+readingParentGuide()+'</div>';app.querySelector('.pr-parent-content').prepend(section);section.querySelectorAll('[data-reading-course]').forEach(b=>b.onclick=()=>skillCourse(b.dataset.readingCourse));};

function readingOpenGuide(courseId){prParents('research');const section=[...app.querySelectorAll('.pr-research-section')].find(d=>d.querySelector('summary')?.textContent==='Letters & starting to read');if(section){section.setAttribute('open','');section.querySelector('summary').focus({preventScroll:true});section.scrollIntoView({block:'start'});}const back=app.querySelector('#prParentBack');if(back)back.onclick=()=>skillCourse(courseId);}
